"""Resolve input-channel configuration for a project.

A Mantle project declares its channels in ``integrations.yml``; a CALM
project uses ``credentials.yml``. The two are distinguished by the same check
as CLI engine selection (:func:`~rasa.shared.engine_version.is_mantle_cli_context`):
a two-of-three Mantle layout, or a Mantle ``--model`` archive next to
``integrations.yml`` when the directory has no ``domain.yml`` and no skills
file. ``integrations.yml`` alone is not enough, so a CALM project that happens
to carry a stray copy still loads ``credentials.yml``. Channel routes are
registered once at startup. A model hot-swapped later does not rebind them.
This module is the single seam that both ``rasa run`` and ``rasa inspect`` go
through when building the :class:`CredentialsConfig`.
"""

from __future__ import annotations

from pathlib import Path
from typing import Optional

import structlog

from rasa.core.config.credentials import CredentialsConfig
from rasa.shared.engine_version import ModelPathArg, is_mantle_cli_context
from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE

structlogger = structlog.get_logger()


def resolve_channels_config(
    credentials_path: Optional[Path] = None,
    project_root: Optional[Path] = None,
    model_path: ModelPathArg = None,
) -> Optional[CredentialsConfig]:
    """Build the channel configuration for CLI startup.

    A Mantle context loads channels exclusively from ``integrations.yml``
    (empty when it declares no ``channels:`` block) and ignores
    ``credentials.yml``. That context is a two-of-three Mantle layout, or a
    Mantle archive passed as *model_path* beside ``integrations.yml`` when the
    directory is not a CALM project and has no skills file. Otherwise channels
    come from ``credentials.yml``, including a CALM project that carries a
    stray ``integrations.yml``. *model_path* is the startup ``--model`` value.
    A model loaded or hot-swapped later does not change the choice.

    Args:
        credentials_path: The raw ``--credentials`` value (unvalidated), or
            ``None``. Only used on the CALM path, where the ``credentials.yml``
            path is validated here rather than by callers.
        project_root: Project directory to read ``integrations.yml`` /
            ``credentials.yml`` from. Defaults to the current working directory,
            which is where ``rasa run`` / ``rasa inspect`` are invoked.
        model_path: Startup model archive, directory of archives, or ``None``.
            Read only for its packaged ``engine_version``.

    Returns:
        A :class:`CredentialsConfig`, or ``None`` when the project has neither an
        ``integrations.yml`` nor a ``credentials.yml``.
    """
    root = project_root or Path.cwd()

    if is_mantle_cli_context(project_root=root, model_path=model_path):
        # Mantle: channels come exclusively from integrations.yml; a missing
        # `channels:` block means no channels, not a fallback to credentials.yml.
        # Imported lazily so CALM runs never pull in the Mantle package.
        from rasa.mantle.config.channels import load_integration_channels

        channels = load_integration_channels(root) or {}
        structlogger.debug(
            "channel_loading.using_integration_channels",
            channel_count=len(channels),
        )
        return CredentialsConfig(channels, root / MANTLE_INTEGRATIONS_FILE)

    # CALM: channels come from credentials.yml. Validate the path here (not in
    # callers) so the lookup is consistent. Imported lazily to avoid a cycle with
    # the configuration module, which imports this one at module load.
    from rasa.core.config.configuration import CredentialsConfigPath

    validated_path = CredentialsConfigPath.validate(credentials_path)
    if validated_path is None:
        return None
    return CredentialsConfig.load_from_file(validated_path)
